    const countrySelect = phoneGroup.querySelector(
      'select[name="phoneCountry"]'
    );
    if (countrySelect) {
      setSnapshotValue(
        snapshot,
        answer.getAdpWorkforceNowPhoneCountryCodeLabel(phoneLabel) || `${phoneLabel} Country`,
        getNativeSelectDisplayValue(countrySelect)
      );
    }
